using System.Windows;using LabMaster.Services;namespace LabMaster;public partial class InventoryHistoryWindow:Window{readonly InventoryService service=new();readonly int itemId;readonly string itemName;public InventoryHistoryWindow(int id,string name){InitializeComponent();itemId=id;itemName=name;TitleText.Text=$"Inventory History — {name}";Loaded+=async(_,_)=>await LoadAsync();}async Task LoadAsync(){try{Grid.ItemsSource=await service.GetTransactionsAsync(itemId);}catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}}